import numpy as np

lib = None
for f in files:
    if f['file_id'] == '2026-08-05/reference_library.csv':
        lib = f['table']
        break

# Print first 10 rows of the table for debugging
print("First 10 rows of library:")
for i in range(10):
    print(f"Row {i}: {lib['material'][i]}, {lib['raman_shift_cm-1'][i]}, {lib['intensity'][i]}")

# Try to find silicon peaks using a simple loop instead of boolean masking if it's buggy
si_peaks = []
for i in range(len(lib['material'])):
    if lib['material'][i] == 'silicon':
        # We only need the peak, so we can look for high intensity near 520
        if 515 <= lib['raman_shift_cm-1'][i] <= 525:
            si_peaks.append((lib['raman_shift_cm-1'][i], lib['intensity'][i]))

if si_peaks:
    best_peak = max(si_peaks, key=lambda x: x[1])
    print(f"Found silicon peak at {best_peak[0]} with intensity {best_peak[1]}")
else:
    print("No silicon peaks found using loop")

# Let's check T123 again just to be sure of the position
t123 = None
for f in files:
    if f['file_id'] == '2026-08-05/T123.csv':
        t123 = f['table']
        break

x_t = t123['raman_shift_cm-1']
y_t = t123['intensity']
mask_t = (x_t >= 510) & (x_t <= 530)
peak_pos_t = x_t[mask_t][np.argmax(y_t[mask_t])]
print(f"T123 Peak: {peak_pos_t}")
